"use client";
import React, { useState } from "react";
import { Plus, Minus, Search, ArrowRight } from "lucide-react";
import { faqData, FAQItem } from "@/data/faq"; // Adjust path as needed

export default function FAQPage() {
  const [activeId, setActiveId] = useState<string | null>(null);
  const [filter, setFilter] = useState<string>("All");

  const categories = [
    "All",
    "Shipping",
    "Orders",
    "Returns",
    "Sizing",
    "Partnerships",
  ];

  const filteredFaqs =
    filter === "All"
      ? faqData
      : faqData.filter((item) => item.category === filter);

  return (
    <div className="bg-background text-foreground min-h-screen pb-32 transition-colors duration-500">
      {/* 1. EDITORIAL HEADER */}
      <section className="pt-32 pb-20 px-6">
        <div className="max-w-7xl mx-auto space-y-8">
          <div className="flex flex-col md:flex-row md:items-end justify-between gap-8">
            <div className="space-y-4">
              <span className="text-[10px] font-black uppercase tracking-[0.4em] text-brand border-l-2 border-brand pl-4">
                Knowledge Base / 2026
              </span>
              <h1 className="text-6xl md:text-8xl font-black uppercase tracking-tighter italic leading-none">
                General <br />{" "}
                <span className="text-foreground-subtle">Inquiries.</span>
              </h1>
            </div>

            {/* SEARCH BAR (Curved) */}
            <div className="relative w-full md:w-80 group">
              <Search
                className="absolute left-6 top-1/2 -translate-y-1/2 opacity-30 group-focus-within:text-brand transition-colors"
                size={18}
              />
              <input
                type="text"
                placeholder="SEARCH ARCHIVE..."
                className="w-full bg-background-muted rounded-full py-5 pl-14 pr-6 border border-border focus:border-brand outline-none uppercase font-black tracking-widest text-[10px] transition-all"
              />
            </div>
          </div>

          {/* CATEGORY FILTERS (Curved) */}
          <div className="flex flex-wrap gap-3 pt-8">
            {categories.map((cat) => (
              <button
                key={cat}
                onClick={() => setFilter(cat)}
                className={`px-8 py-3 rounded-full text-[10px] font-black uppercase tracking-widest border transition-all ${
                  filter === cat
                    ? "bg-brand text-brand-foreground border-brand"
                    : "bg-transparent border-border hover:border-brand"
                }`}
              >
                {cat}
              </button>
            ))}
          </div>
        </div>
      </section>

      {/* 2. ACCORDION SECTION */}
      <section className="max-w-4xl mx-auto px-6">
        <div className="space-y-4">
          {filteredFaqs.map((faq) => (
            <div
              key={faq.id}
              className={`rounded-[2.5rem] border transition-all duration-500 overflow-hidden ${
                activeId === faq.id
                  ? "bg-background-muted border-brand"
                  : "bg-background border-border"
              }`}
            >
              <button
                onClick={() => setActiveId(activeId === faq.id ? null : faq.id)}
                className="w-full px-8 py-8 flex items-center justify-between text-left group"
              >
                <div className="space-y-2">
                  <span className="text-[9px] font-black uppercase tracking-[0.3em] opacity-40 italic">
                    [{faq.category}]
                  </span>
                  <h3 className="text-lg md:text-xl font-black uppercase tracking-tight italic group-hover:translate-x-2 transition-transform">
                    {faq.question}
                  </h3>
                </div>
                <div
                  className={`p-3 rounded-full border border-border transition-all ${
                    activeId === faq.id
                      ? "rotate-180 bg-brand text-brand-foreground"
                      : ""
                  }`}
                >
                  {activeId === faq.id ? (
                    <Minus size={20} />
                  ) : (
                    <Plus size={20} />
                  )}
                </div>
              </button>

              <div
                className={`transition-all duration-500 ease-in-out ${
                  activeId === faq.id
                    ? "max-h-96 opacity-100"
                    : "max-h-0 opacity-0"
                }`}
              >
                <div className="px-8 pb-10">
                  <p className="text-foreground-muted leading-relaxed font-medium italic border-t border-border pt-6">
                    {faq.answer}
                  </p>
                </div>
              </div>
            </div>
          ))}
        </div>
      </section>

      {/* 3. CTA FOR FURTHER HELP */}
      <section className="max-w-7xl mx-auto px-6 mt-32">
        <div className="bg-brand text-brand-foreground rounded-[4rem] p-12 md:p-24 text-center space-y-8 relative overflow-hidden group">
          <div className="relative z-10">
            <h2 className="text-4xl md:text-6xl font-black uppercase tracking-tighter italic">
              Still have questions?
            </h2>
            <p className="max-w-md mx-auto opacity-70 font-medium italic text-sm">
              Our styling architects and support nodes are standing by for
              direct transmission.
            </p>
            <button className="mt-8 bg-brand-foreground text-brand px-12 py-6 rounded-full font-black uppercase tracking-[0.3em] text-[11px] hover:scale-105 transition-all inline-flex items-center gap-4">
              Contact Concierge <ArrowRight size={16} />
            </button>
          </div>
          {/* Decorative background circle */}
          <div className="absolute -bottom-20 -right-20 w-96 h-96 bg-white/10 rounded-full blur-3xl group-hover:scale-150 transition-transform duration-700" />
        </div>
      </section>
    </div>
  );
}
